#!/usr/bin/env python3
import json
import os
import re
import shutil
import zipfile
from pathlib import Path
import xml.etree.ElementTree as ET

TEMPLATE_PATH = '/root/training_feedback_template.hwpx'
JSON_PATH = '/root/training_feedback.json'
OUT_PATH = '/root/training_feedback_ready.hwpx'

WORK_DIR = Path('/tmp/hwpx_work')
EXTRACT_DIR = WORK_DIR / 'extracted'

PLACEHOLDER_RE = re.compile(r'\{\{\s*([^{}\s]+)\s*\}\}')


def digits_only(value) -> str:
    if value is None:
        return ''
    s = str(value)
    return ''.join(ch for ch in s if ch.isdigit())


def normalize_satisfaction(value) -> str:
    if value is None:
        score = ''
    else:
        s = str(value).strip()
        # Accept forms like: 4.5, "4.5", "4.5/5.0", "4.5 / 5.0"
        m = re.search(r'(\d+(?:\.\d+)?)', s)
        score = m.group(1) if m else s
    return f'{score}점 (5.0점 만점)'


def append_followup_sentence(value) -> str:
    base = '' if value is None else str(value)
    suffix = '후속 심화반 검토 요망.'
    if base.endswith(suffix):
        return base
    if base and not base.endswith(' '):
        base = base + ' '
    return base + suffix


def build_replacements(data: dict) -> dict:
    repl = {}
    for k, v in data.items():
        repl[k] = '' if v is None else str(v)

    # Apply transformation rules
    if '참석자수' in repl:
        repl['참석자수'] = digits_only(data.get('참석자수'))
    if '만족도' in repl:
        repl['만족도'] = normalize_satisfaction(data.get('만족도'))
    if '종합의견' in repl:
        repl['종합의견'] = append_followup_sentence(data.get('종합의견'))

    return repl


def is_layout_cache_tag(tag: str) -> bool:
    # tag might be "{namespace}local" or "local"
    lower = tag.lower()
    return ('lineseg' in lower) or ('layoutcache' in lower)


def remove_layout_caches_in_paragraph(paragraph_elem: ET.Element) -> bool:
    """Remove layout cache elements under this paragraph. Returns True if any removed."""
    removed = False

    def recurse(parent: ET.Element):
        nonlocal removed
        # Iterate over a snapshot because we may remove children.
        for child in list(parent):
            if is_layout_cache_tag(child.tag):
                parent.remove(child)
                removed = True
            else:
                recurse(child)

    recurse(paragraph_elem)
    return removed


def paragraph_text_elements(paragraph_elem: ET.Element):
    """Return list of text elements (any namespace) that look like text nodes."""
    # In HWPML HWPX, text is in <hp:t>
    text_elems = []
    for elem in paragraph_elem.iter():
        if elem.tag.endswith('}t') or elem.tag == 't':
            text_elems.append(elem)
    return text_elems


def replace_placeholders_in_paragraph(paragraph_elem: ET.Element, replacements: dict) -> bool:
    """Replace placeholders within a paragraph, even if split across multiple <t> runs.

    Strategy:
    - Collect all <t> elements in order within paragraph
    - Concatenate their .text ('' if None)
    - Replace placeholders in the concatenated string
    - If changed, write full new string into first <t>, clear rest

    Returns True if text was modified.
    """
    t_elems = paragraph_text_elements(paragraph_elem)
    if not t_elems:
        return False

    texts = [(e.text or '') for e in t_elems]
    joined = ''.join(texts)

    def repl_fn(match: re.Match) -> str:
        key = match.group(1)
        if key in replacements:
            return replacements[key]
        # If missing, leave as-is to make it detectable in verification.
        return match.group(0)

    replaced = PLACEHOLDER_RE.sub(repl_fn, joined)
    if replaced == joined:
        return False

    t_elems[0].text = replaced
    for e in t_elems[1:]:
        e.text = ''

    return True


def register_namespaces_from_file(xml_path: Path):
    for event, elem in ET.iterparse(str(xml_path), events=('start-ns',)):
        prefix, uri = elem
        # Avoid ValueError for duplicate registrations
        try:
            ET.register_namespace(prefix if prefix is not None else '', uri)
        except Exception:
            pass


def process_xml_file(xml_path: Path, replacements: dict) -> dict:
    """Process a single XML file. Returns stats."""
    register_namespaces_from_file(xml_path)

    tree = ET.parse(str(xml_path))
    root = tree.getroot()

    modified_paragraphs = 0
    removed_cache_paragraphs = 0

    # HWPX paragraphs are <hp:p>
    for p in root.iter():
        if p.tag.endswith('}p') or p.tag == 'p':
            changed = replace_placeholders_in_paragraph(p, replacements)
            if changed:
                modified_paragraphs += 1
                if remove_layout_caches_in_paragraph(p):
                    removed_cache_paragraphs += 1

    if modified_paragraphs:
        tree.write(str(xml_path), encoding='utf-8', xml_declaration=True)

    return {
        'file': str(xml_path),
        'modified_paragraphs': modified_paragraphs,
        'removed_cache_paragraphs': removed_cache_paragraphs,
    }


def extract_hwpx(src: str, dst_dir: Path):
    if dst_dir.exists():
        shutil.rmtree(dst_dir)
    dst_dir.mkdir(parents=True, exist_ok=True)
    with zipfile.ZipFile(src) as z:
        z.extractall(dst_dir)


def repack_hwpx(src_dir: Path, out_path: str):
    out_tmp = str(out_path) + '.tmp'
    if os.path.exists(out_tmp):
        os.remove(out_tmp)

    # Collect all files
    files = []
    for root, _, filenames in os.walk(src_dir):
        for fn in filenames:
            full = os.path.join(root, fn)
            rel = os.path.relpath(full, src_dir)
            files.append((rel, full))

    # Ensure deterministic order, but keep "mimetype" first if present
    files.sort(key=lambda x: x[0])
    mimetype = [x for x in files if x[0] == 'mimetype']
    rest = [x for x in files if x[0] != 'mimetype']

    with zipfile.ZipFile(out_tmp, 'w') as z:
        if mimetype:
            rel, full = mimetype[0]
            z.write(full, rel, compress_type=zipfile.ZIP_STORED)
        for rel, full in rest:
            z.write(full, rel, compress_type=zipfile.ZIP_DEFLATED)

    os.replace(out_tmp, out_path)


def main():
    with open(JSON_PATH, 'r', encoding='utf-8') as f:
        data = json.load(f)

    replacements = build_replacements(data)

    extract_hwpx(TEMPLATE_PATH, EXTRACT_DIR)

    stats = []
    # Only process XML files under extracted folder
    for root, _, files in os.walk(EXTRACT_DIR):
        for fn in files:
            if not fn.lower().endswith('.xml'):
                continue
            xml_path = Path(root) / fn
            # Cheap scan before parse
            try:
                raw = xml_path.read_text(encoding='utf-8')
            except UnicodeDecodeError:
                raw = xml_path.read_text(encoding='utf-8', errors='replace')
            if '{{' not in raw:
                continue
            stats.append(process_xml_file(xml_path, replacements))

    repack_hwpx(EXTRACT_DIR, OUT_PATH)

    # Print summary for logs
    total_mod = sum(s['modified_paragraphs'] for s in stats)
    total_cache = sum(s['removed_cache_paragraphs'] for s in stats)
    print('processed_files:', len(stats))
    for s in stats:
        print(f"{s['file']}: modified_paragraphs={s['modified_paragraphs']} removed_cache_paragraphs={s['removed_cache_paragraphs']}")
    print('total_modified_paragraphs:', total_mod)
    print('total_removed_cache_paragraphs:', total_cache)
    print('wrote:', OUT_PATH)


if __name__ == '__main__':
    main()
