    for e in t_elems[1:]:
        e.text = ''

    return True


def register_namespaces_from_file(xml_path: Path):
    for event, elem in ET.iterparse(str(xml_path), events=('start-ns',)):
        prefix, uri = elem
        # Avoid ValueError for duplicate registrations
        try:
            ET.register_namespace(prefix if prefix is not None else '', uri)
        except Exception:
            pass


def process_xml_file(xml_path: Path, replacements: dict) -> dict:
    """Process a single XML file. Returns stats."""
    register_namespaces_from_file(xml_path)

    tree = ET.parse(str(xml_path))
    root = tree.getroot()

    modified_paragraphs = 0
    removed_cache_paragraphs = 0

    # HWPX paragraphs are <hp:p>
    for p in root.iter():
        if p.tag.endswith('}p') or p.tag == 'p':
            changed = replace_placeholders_in_paragraph(p, replacements)
            if changed:
                modified_paragraphs += 1
                if remove_layout_caches_in_paragraph(p):
                    removed_cache_paragraphs += 1

    if modified_paragraphs:
        tree.write(str(xml_path), encoding='utf-8', xml_declaration=True)

    return {
        'file': str(xml_path),
        'modified_paragraphs': modified_paragraphs,
        'removed_cache_paragraphs': removed_cache_paragraphs,
    }


def extract_hwpx(src: str, dst_dir: Path):
    if dst_dir.exists():
        shutil.rmtree(dst_dir)
    dst_dir.mkdir(parents=True, exist_ok=True)
    with zipfile.ZipFile(src) as z:
        z.extractall(dst_dir)


def repack_hwpx(src_dir: Path, out_path: str):
    out_tmp = str(out_path) + '.tmp'
    if os.path.exists(out_tmp):
        os.remove(out_tmp)

    # Collect all files
    files = []
    for root, _, filenames in os.walk(src_dir):
        for fn in filenames:
            full = os.path.join(root, fn)
            rel = os.path.relpath(full, src_dir)
            files.append((rel, full))

    # Ensure deterministic order, but keep "mimetype" first if present
    files.sort(key=lambda x: x[0])
    mimetype = [x for x in files if x[0] == 'mimetype']
    rest = [x for x in files if x[0] != 'mimetype']

    with zipfile.ZipFile(out_tmp, 'w') as z:
        if mimetype:
            rel, full = mimetype[0]
            z.write(full, rel, compress_type=zipfile.ZIP_STORED)
        for rel, full in rest:
            z.write(full, rel, compress_type=zipfile.ZIP_DEFLATED)

    os.replace(out_tmp, out_path)


def main():
    with open(JSON_PATH, 'r', encoding='utf-8') as f:
        data = json.load(f)

    replacements = build_replacements(data)

    extract_hwpx(TEMPLATE_PATH, EXTRACT_DIR)

    stats = []
    # Only process XML files under extracted folder
    for root, _, files in os.walk(EXTRACT_DIR):
        for fn in files:
            if not fn.lower().endswith('.xml'):
                continue
            xml_path = Path(root) / fn
            # Cheap scan before parse
            try:
                raw = xml_path.read_text(encoding='utf-8')
            except UnicodeDecodeError:
                raw = xml_path.read_text(encoding='utf-8', errors='replace')
            if '{{' not in raw:
                continue
            stats.append(process_xml_file(xml_path, replacements))

    repack_hwpx(EXTRACT_DIR, OUT_PATH)

    # Print summary for logs
    total_mod = sum(s['modified_paragraphs'] for s in stats)
    total_cache = sum(s['removed_cache_paragraphs'] for s in stats)
    print('processed_files:', len(stats))
    for s in stats:
        print(f"{s['file']}: modified_paragraphs={s['modified_paragraphs']} removed_cache_paragraphs={s['removed_cache_paragraphs']}")
    print('total_modified_paragraphs:', total_mod)
    print('total_removed_cache_paragraphs:', total_cache)
    print('wrote:', OUT_PATH)


if __name__ == '__main__':
    main()
